import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from dataset import get_dataloader
import json
from tqdm import tqdm

DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
train_loader = get_dataloader(DATA_DIR, METADATA_FILE, batch_size=32)

class BirdCLEFModel(nn.Module):
    def __init__(self, num_classes=234):
        super(BirdCLEFModel, self).__init__()
        self.conv1 = nn.Conv2d(1, 32, kernel_size=(5, 5), stride=(2, 2), padding=2)
        self.bn1 = nn.BatchNorm2d(32)
        self.conv2 = nn.Conv2d(32, 64, kernel_size=(5, 5), stride=(2, 2), padding=2)
        self.bn2 = nn.BatchNorm2d(64)
        self.conv3 = nn.Conv2d(64, 128, kernel_size=(3, 3), stride=(1, 1), padding=1)
        self.bn3 = nn.BatchNorm2d(128)
        self.pool = nn.AdaptiveAvgPool2d(output_size=(1, 1))
        self.fc = nn.Linear(128, num_classes)

    def forward(self, x):
        x = F.relu(self.bn1(self.conv1(x)))
        x = F.relu(self.bn2(self.conv2(x)))
        x = F.relu(self.bn3(self.conv3(x)))
        x = self.pool(x)
        x = x.view(x.size(0), -1)
        x = torch.sigmoid(self.fc(x))
        return x

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
model = BirdCLEFModel().to(device)

criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=0.001)

# Limit training to first 5000 samples for quick iteration
num_samples = 5000
train_loader.dataset.data = train_loader.dataset.data[:num_samples]
train_loader.dataset.labels = train_loader.dataset.labels[:num_samples]

epochs_trained = 3
final_train_loss = None

for epoch in tqdm(range(epochs_trained), desc="Epochs"):
    model.train()
    running_loss = 0.0
    for i, (inputs, labels) in enumerate(train_loader):
        inputs, labels = inputs.to(device), labels.to(device)

        optimizer.zero_grad()
        outputs = model(inputs)
        loss = criterion(outputs, labels.float())
        loss.backward()
        optimizer.step()

        running_loss += loss.item()
    
    final_train_loss = running_loss / len(train_loader)
    print(f"Epoch {epoch+1}, Loss: {final_train_loss:.4f}")
    torch.cuda.empty_cache()

# Evaluate the model
import numpy as np
from sklearn.metrics import roc_auc_score

model.eval()
all_preds = []
all_labels = []
with torch.no_grad():
    for inputs, labels in train_loader:
        inputs, labels = inputs.to(device), labels.to(device)
        outputs = model(inputs)
        all_preds.append(outputs.cpu().numpy())
        all_labels.append(labels.cpu().numpy())

all_preds = np.concatenate(all_preds)
all_labels = np.concatenate(all_labels)

# Calculate AUC
try:
    final_auc = float(roc_auc_score(all_labels, all_preds, average='weighted', multi_class='ovr'))
except:
    # Fallback: if above fails, use sample average
    final_auc = float(roc_auc_score(all_labels.ravel(), all_preds.ravel()))

num_params = sum(p.numel() for p in model.parameters() if p.requires_grad)

metrics = {
    "final_train_loss": final_train_loss,
    "final_auc": final_auc,
    "num_params": num_params,
    "epochs_trained": epochs_trained,
    "batch_size": 32
}

print("METRICS: " + json.dumps(metrics))
with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

# Save the model
torch.save(model.state_dict(), 'model.pt')